 92	function parseCookies(req) {
 93	  const out = {};
 94	  for (const part of (req.headers.cookie || '').split(';')) {
 95	    const i = part.indexOf('=');
 96	    if (i > 0) {
 97	      try {
 98	        out[part.slice(0, i).trim()] = decodeURIComponent(part.slice(i + 1).trim());
 99	      } catch {
100	        /* ignore malformed cookie */
101	      }
102	    }
103	  }
104	  return out;
105	}
