107	function addCookie(res, value) {
108	  const existing = res.getHeader('Set-Cookie');
109	  const list = Array.isArray(existing) ? existing : existing ? [existing] : [];
110	  res.setHeader('Set-Cookie', [...list, value]);
111	}
112	
113	function sendJson(res, status, body, headers = {}) {
114	  const payload = JSON.stringify(body);
115	  res.writeHead(status, {
116	    'Content-Type': 'application/json; charset=utf-8',
117	    'Cache-Control': 'no-store',
118	    ...headers,
119	  });
120	  res.end(payload);
121	}
122	
123	function sendHtml(res, status, html) {
124	  res.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' });
125	  res.end(html);
126	}
