137	/** Identity endpoints answer errors as { error: "message" }. */
138	const identityError = (res, status, message, headers) => sendJson(res, status, { error: message }, headers);
139	
140	/** Order endpoints answer errors as { errors: [{ code, message }] }. */
141	const orderError = (res, status, code, message) => sendJson(res, status, { errors: [{ code, message }] });
142	
143	function readJson(req) {
144	  return new Promise((resolve, reject) => {
145	    let size = 0;
146	    const chunks = [];
147	    req.on('data', (chunk) => {
148	      size += chunk.length;
149	      if (size > 100 * 1024) {
150	        reject(new Error('Body too large'));
151	        req.destroy();
152	        return;
153	      }
154	      chunks.push(chunk);
155	    });
156	    req.on('end', () => {
157	      const raw = Buffer.concat(chunks).toString('utf8').trim();
158	      if (!raw) return resolve({});
159	      try {
160	        resolve(JSON.parse(raw));
161	      } catch {
162	        reject(new Error('Invalid JSON'));
163	      }
164	    });
165	    req.on('error', reject);
166	  });
167	}
