169	function isLocalOrigin(origin) {
170	  return /^https?:\/\/(localhost|127\.0\.0\.1)(:\d+)?$/.test(origin);
171	}
172	
173	function isAllowedOrigin(origin) {
174	  return Boolean(origin) && (isLocalOrigin(origin) || origin === WEB_ORIGIN || EXTRA_ORIGINS.includes(origin));
175	}
176	
177	function isAllowedReturnUrl(value) {
178	  try {
179	    const u = new URL(value);
180	    if (u.protocol !== 'http:' && u.protocol !== 'https:') return false;
181	    return isAllowedOrigin(u.origin);
182	  } catch {
183	    return false;
184	  }
185	}
