211	/** Precedence: x-scenario header, then ?scenario= query, then cookie, then "happy". */
212	function resolveScenario(req, url, cookies) {
213	  const name = req.headers['x-scenario'] || url.searchParams.get('scenario') || cookies[SCENARIO_COOKIE] || 'happy';
