217	function getCustomer(ctx) {
218	  const session = state.sessions.get(ctx.cookies[SESSION_COOKIE]);
219	  if (!session || Date.now() - session.createdAt > SESSION_TTL_MS) return null;
220	  const customer = state.customers.get(session.customerId);
221	  if (!customer) return null;
222	  applyPaidOrders(customer);
223	  return customer;
