231	function applyPaidOrders(customer) {
232	  for (const order of state.orders.values()) {
233	    if (order.customerId === customer.id && !order.applied && orderStatus(order) === 'paid') {
234	      order.applied = true;
235	      customer.trialUsed = true;
236	      customer.subscription = {
237	        planId: order.planId,
238	        status: 'active',
239	        renewsAt: new Date(Date.now() + 30 * 24 * 3600 * 1000).toISOString(),
240	      };
241	    }
242	  }
243	}
