530	   530	// ---------------------------------------------------------------------------
531	   531	// Router
532	   532	// ---------------------------------------------------------------------------
533	   533	
534	   534	async function route(ctx) {
535	   535	  const { req, res, url } = ctx;
536	   536	  const p = url.pathname.replace(/\/+$/, '') || '/';
537	   537	  const m = req.method;
538	   538	  let match;
539	   539	
540	   540	  if (m === 'GET' && p === '/') return sendHtml(res, 200, landingPage(req, ctx.scenario));
541	   541	  if (m === 'GET' && p === '/v1/plans') return handlePlans(ctx);
542	   542	  if (m === 'POST' && p === '/v1/identity/sessions') return handleCreateIdentitySession(ctx);
543	   543	  if (m === 'GET' && p === '/v1/me') return handleMe(ctx);
544	   544	  if (m === 'POST' && p === '/v1/orders') return handleCreateOrder(ctx);
545	   545	  if (m === 'GET' && (match = p.match(/^\/v1\/orders\/([\w-]+)$/))) return handleGetOrder(ctx, match[1]);
546	   546	
547	   547	  if (m === 'GET' && (match = p.match(/^\/mock-eid\/([\w-]+)$/))) return handleEidPage(ctx, match[1]);
548	   548	  if (m === 'GET' && (match = p.match(/^\/mock-eid\/([\w-]+)\/complete$/))) return handleEidComplete(ctx, match[1]);
549	   549	  if (m === 'GET' && (match = p.match(/^\/mock-pay\/([\w-]+)$/))) return handlePayPage(ctx, match[1]);
550	   550	  if (m === 'GET' && (match = p.match(/^\/mock-pay\/([\w-]+)\/submit$/))) return handlePaySubmit(ctx, match[1]);
551	   551	  if (m === 'GET' && (match = p.match(/^\/mock-pay\/([\w-]+)\/challenge$/))) return handleChallengePage(ctx, match[1]);
552	   552	  if (m === 'GET' && (match = p.match(/^\/mock-pay\/([\w-]+)\/challenge\/complete$/))) return handleChallengeComplete(ctx, match[1]);
553	   553	
554	   554	  if (m === 'GET' && p === '/cms/v1/plan-pages') return handleCms(ctx);
555	   555	
556	   556	  if (m === 'GET' && (match = p.match(/^\/__mock\/scenario\/([\w]+)$/))) {
557	   557	    if (!Object.prototype.hasOwnProperty.call(SCENARIOS, match[1])) return identityError(res, 404, 'Unknown scenario');
558	   558	    addCookie(res, `${SCENARIO_COOKIE}=${match[1]}; Path=/; SameSite=Lax; Max-Age=3600`);
559	   559	    return redirect(res, '/');
560	   560	  }
561	   561	  if ((m === 'POST' || m === 'GET') && p === '/__mock/reset') {
562	   562	    resetState();
563	   563	    return m === 'GET' ? redirect(res, '/') : sendJson(res, 200, { ok: true });
564	   564	  }
565	   565	  if (m === 'GET' && p === '/__mock/state') {
566	   566	    return sendJson(res, 200, {
567	   567	      scenario: ctx.scenario,
568	   568	      sessions: state.sessions.size,
569	   569	      customers: [...state.customers.values()],
570	   570	      identitySessions: state.identitySessions.size,
571	   571	      orders: [...state.orders.values()].map((o) => ({ id: o.id, planId: o.planId, status: orderStatus(o), scenario: o.scenario })),
572	   572	    });
573	   573	  }
574	   574	
575	   575	  return identityError(res, 404, 'Not found');
576	   576	}
577	   577	
578	   578	async function handle(req, res) {
579	   579	  const url = new URL(req.url, 'http://mock.local');
580	   580	  setCors(req, res);
581	   581	  if (req.method === 'OPTIONS') {
582	   582	    res.writeHead(204);
583	   583	    return res.end();
584	   584	  }
585	   585	  const cookies = parseCookies(req);
586	   586	  const scenario = resolveScenario(req, url, cookies);
587	   587	  if (!scenario) {
588	   588	    return identityError(res, 400, `Unknown scenario. Valid: ${Object.keys(SCENARIOS).join(', ')}`);
589	   589	  }
590	   590	  if (url.searchParams.get('scenario') && !req.headers['x-scenario']) {
591	   591	    addCookie(res, `${SCENARIO_COOKIE}=${scenario}; Path=/; SameSite=Lax; Max-Age=3600`);
592	   592	  }
593	   593	  const started = Date.now();
594	   594	  res.on('finish', () => {
595	   595	    if (!process.env.MOCK_QUIET) {
596	   596	      console.log(`${req.method} ${url.pathname} [${scenario}] -> ${res.statusCode} (${Date.now() - started}ms)`);
597	   597	    }
598	   598	  });
599	   599	  try {
600	   600	    await route({ req, res, url, cookies, scenario });
601	   601	  } catch (err) {
602	   602	    console.error(err);
603	   603	    if (!res.headersSent) identityError(res, 500, 'Mock server error');
604	   604	  }
605	   605	}
606	   606	
607	   607	function createServer() {
608	   608	  return http.createServer((req, res) => {
609	   609	    handle(req, res);
610	   610	  });
611	   611	}
612	   612	
613	   613	if (require.main === module) {
614	   614	  const server = createServer();
615	   615	  server.on('error', (err) => {
616	   616	    if (err.code === 'EADDRINUSE') console.error(`Port ${PORT} is in use. Set PORT=<other> and try again.`);
617	   617	    else console.error(err);
618	   618	    process.exit(1);
619	   619	  });
620	   620	  server.listen(PORT, HOST, () => {
621	   621	    console.log(`Nordlight mock server on http://${HOST === '127.0.0.1' ? 'localhost' : HOST}:${PORT}`);
622	   622	    console.log(`Web origin for redirects: ${WEB_ORIGIN}   time scale: ${TIME_SCALE}x`);
623	   623	    console.log('Open the address above to see and switch scenarios.');
624	   624	  });
625	   625	}
626	   626	
627	   627	module.exports = { createServer, resetState, SCENARIOS };
