 45	  rate_limited: 'POST /v1/identity/sessions answers 429 with a Retry-After header.',
 46	  already_subscribed: 'GET /v1/me reports an active subscription.',
 47	  not_trial_eligible: 'GET /v1/me reports trialEligible: false.',
 48	  payment_declined: 'The payment provider declines the payment.',
 49	  payment_slow: 'Payment is confirmed about 45 seconds after the customer pays.',
 50	  payment_requires_action: 'The provider asks for an extra authentication step before it confirms payment.',
 51	  api_500: 'Every /v1 endpoint except GET /v1/plans answers 500.',
 52	};
 53	
 54	const VAT = { EE: 0.24, LV: 0.21, LT: 0.21 };
 55	
 56	const ALL_PLANS = [
 57	  { id: 'plan_basic_m', name: 'Basic', priceNet: 599 },
 58	  { id: 'plan_std_m', name: 'Standard', priceNet: 899 },
 59	  { id: 'plan_prem_m', name: 'Premium', priceNet: 1299 },
 60	];
 61	
 62	const MARKET_PLAN_IDS = {
 63	  EE: ['plan_basic_m', 'plan_std_m', 'plan_prem_m'],
 64	  LT: ['plan_basic_m', 'plan_std_m', 'plan_prem_m'],
 65	  LV: ['plan_basic_m', 'plan_std_m'],
 66	};
 67	
 68	// ---------------------------------------------------------------------------
 69	// In-memory state
 70	// ---------------------------------------------------------------------------
 71	
 72	const state = {
 73	  sessions: new Map(), // sessionId -> { customerId, createdAt }
 74	  customers: new Map(), // customerId -> { id, subscription, trialUsed }
 75	  identitySessions: new Map(), // id -> { id, createdAt, returnUrl, scenario, completed }
 76	  orders: new Map(), // id -> order
 77	};
 78	
 79	function resetState() {
 80	  state.sessions.clear();
 81	  state.customers.clear();
 82	  state.identitySessions.clear();
 83	  state.orders.clear();
 84	}
 85	
 86	const rid = (prefix, bytes = 6) => `${prefix}_${crypto.randomBytes(bytes).toString('hex')}`;
 87	
 88	// ---------------------------------------------------------------------------
 89	// HTTP helpers
 90	// ---------------------------------------------------------------------------
 91	
 92	function parseCookies(req) {
 93	  const out = {};
 94	  for (const part of (req.headers.cookie || '').split(';')) {
 95	    const i = part.indexOf('=');
 96	    if (i > 0) {
 97	      try {
 98	        out[part.slice(0, i).trim()] = decodeURIComponent(part.slice(i + 1).trim());
 99	      } catch {
100	        /* ignore malformed cookie */
101	      }
102	    }
103	  }
104	  return out;
105	}
106	
107	function addCookie(res, value) {
108	  const existing = res.getHeader('Set-Cookie');
109	  const list = Array.isArray(existing) ? existing : existing ? [existing] : [];
110	  res.setHeader('Set-Cookie', [...list, value]);
111	}
112	
113	function sendJson(res, status, body, headers = {}) {
114	  const payload = JSON.stringify(body);
115	  res.writeHead(status, {
116	    'Content-Type': 'application/json; charset=utf-8',
117	    'Cache-Control': 'no-store',
118	    ...headers,
119	  });
120	  res.end(payload);
121	}
122	
123	function sendHtml(res, status, html) {
124	  res.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' });
125	  res.end(html);
126	}
127	
128	function redirect(res, location) {
129	  res.writeHead(302, { Location: location, 'Cache-Control': 'no-store' });
130	  res.end();
131	}
132	
133	function esc(value) {
134	  return String(value).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
135	}
136	
137	/** Identity endpoints answer errors as { error: "message" }. */
138	const identityError = (res, status, message, headers) => sendJson(res, status, { error: message }, headers);
139	
140	/** Order endpoints answer errors as { errors: [{ code, message }] }. */
141	const orderError = (res, status, code, message) => sendJson(res, status, { errors: [{ code, message }] });
142	
143	function readJson(req) {
144	  return new Promise((resolve, reject) => {
145	    let size = 0;
146	    const chunks = [];
147	    req.on('data', (chunk) => {
148	      size += chunk.length;
149	      if (size > 100 * 1024) {
150	        reject(new Error('Body too large'));
151	        req.destroy();
152	        return;
153	      }
154	      chunks.push(chunk);
155	    });
156	    req.on('end', () => {
157	      const raw = Buffer.concat(chunks).toString('utf8').trim();
158	      if (!raw) return resolve({});
159	      try {
160	        resolve(JSON.parse(raw));
161	      } catch {
162	        reject(new Error('Invalid JSON'));
163	      }
164	    });
165	    req.on('error', reject);
166	  });
167	}
168	
169	function isLocalOrigin(origin) {
170	  return /^https?:\/\/(localhost|127\.0\.0\.1)(:\d+)?$/.test(origin);
171	}
172	
173	function isAllowedOrigin(origin) {
174	  return Boolean(origin) && (isLocalOrigin(origin) || origin === WEB_ORIGIN || EXTRA_ORIGINS.includes(origin));
175	}
176	
177	function isAllowedReturnUrl(value) {
178	  try {
179	    const u = new URL(value);
180	    if (u.protocol !== 'http:' && u.protocol !== 'https:') return false;
181	    return isAllowedOrigin(u.origin);
182	  } catch {
183	    return false;
184	  }
185	}
186	
187	function setCors(req, res) {
188	  const origin = req.headers.origin;
189	  if (isAllowedOrigin(origin)) {
190	    res.setHeader('Access-Control-Allow-Origin', origin);
191	    res.setHeader('Access-Control-Allow-Credentials', 'true');
192	    res.setHeader('Vary', 'Origin');
193	    res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
194	    res.setHeader('Access-Control-Allow-Headers', 'content-type, x-scenario');
195	    res.setHeader('Access-Control-Expose-Headers', 'retry-after');
196	  }
197	}
198	
199	function withParams(base, params) {
200	  const u = new URL(base);
201	  for (const [k, v] of Object.entries(params)) u.searchParams.set(k, v);
202	  return u.toString();
203	}
204	
205	const selfOrigin = (req) => process.env.MOCK_ORIGIN || `http://${req.headers.host || `localhost:${PORT}`}`;
206	
207	// ---------------------------------------------------------------------------
208	// Scenario, session, order helpers
209	// ---------------------------------------------------------------------------
210	
211	/** Precedence: x-scenario header, then ?scenario= query, then cookie, then "happy". */
212	function resolveScenario(req, url, cookies) {
213	  const name = req.headers['x-scenario'] || url.searchParams.get('scenario') || cookies[SCENARIO_COOKIE] || 'happy';
214	  return Object.prototype.hasOwnProperty.call(SCENARIOS, name) ? name : null;
215	}
216	
217	function getCustomer(ctx) {
218	  const session = state.sessions.get(ctx.cookies[SESSION_COOKIE]);
219	  if (!session || Date.now() - session.createdAt > SESSION_TTL_MS) return null;
220	  const customer = state.customers.get(session.customerId);
221	  if (!customer) return null;
222	  applyPaidOrders(customer);
223	  return customer;
224	}
225	
226	function orderStatus(order) {
227	  if (order.outcome) return Date.now() >= order.settleAt ? order.outcome : 'pending';
228	  return order.awaitingAction ? 'requires_action' : 'pending';
229	}
230	
231	function applyPaidOrders(customer) {
232	  for (const order of state.orders.values()) {
233	    if (order.customerId === customer.id && !order.applied && orderStatus(order) === 'paid') {
234	      order.applied = true;
235	      customer.trialUsed = true;
236	      customer.subscription = {
237	        planId: order.planId,
238	        status: 'active',
239	        renewsAt: new Date(Date.now() + 30 * 24 * 3600 * 1000).toISOString(),
240	      };
241	    }
242	  }
243	}
244	
245	function orderReturnUrl(order, extra = {}) {
246	  return withParams(order.returnUrl, { orderId: order.id, ...extra });
247	}
248	
249	// ---------------------------------------------------------------------------
250	// HTML pages for the fake hosted providers
251	// ---------------------------------------------------------------------------
252	
