341	function handlePlans(ctx) {
342	  const market = (ctx.url.searchParams.get('market') || '').toUpperCase();
343	  if (!MARKET_PLAN_IDS[market]) return identityError(ctx.res, 400, 'Unknown or missing market. Use EE, LV or LT.');
