354	async function handleCreateIdentitySession(ctx) {
355	  const { req, res, scenario } = ctx;
356	  if (scenario === 'api_500') return identityError(res, 500, 'Internal error');
357	  if (scenario === 'rate_limited') return identityError(res, 429, 'Too many requests', { 'Retry-After': '30' });
358	  let body;
359	  try {
360	    body = await readJson(req);
361	  } catch (err) {
362	    return identityError(res, 400, err.message);
363	  }
364	  const returnUrl = body.returnUrl || `${WEB_ORIGIN}/auth/callback`;
365	  if (!isAllowedReturnUrl(returnUrl)) return identityError(res, 400, 'returnUrl is not allowed');
366	  const id = rid('ids', 8);
367	  state.identitySessions.set(id, { id, createdAt: Date.now(), returnUrl, scenario, completed: false });
