381	  if (!s) return sendHtml(res, 404, providerPage('Not found', '<h1>Unknown eID session</h1>'));
382	  if (s.completed || Date.now() - s.createdAt > IDENTITY_TTL_MS) {
383	    return redirect(res, withParams(s.returnUrl, { status: 'expired' }));
384	  }
385	  s.completed = true;
386	  if (url.searchParams.get('result') !== 'ok') {
387	    return redirect(res, withParams(s.returnUrl, { status: 'cancelled' }));
