391	  const sessionId = rid('ses', 12);
392	  state.sessions.set(sessionId, { customerId, createdAt: Date.now() });
393	  addCookie(res, `${SESSION_COOKIE}=${sessionId}; Path=/; HttpOnly; SameSite=Lax; Max-Age=${SESSION_TTL_MS / 1000}`);
394	  return redirect(res, withParams(s.returnUrl, { status: 'ok' }));
395	}
