397	function handleMe(ctx) {
398	  const { res, scenario } = ctx;
399	  if (scenario === 'api_500') return identityError(res, 500, 'Internal error');
400	  const customer = getCustomer(ctx);
401	  if (!customer) return identityError(res, 401, 'Not identified');
