410	async function handleCreateOrder(ctx) {
411	  const { req, res, scenario } = ctx;
412	  if (scenario === 'api_500') return orderError(res, 500, 'internal_error', 'Something went wrong.');
413	  const customer = getCustomer(ctx);
414	  if (!customer) return orderError(res, 401, 'unauthenticated', 'Identify yourself first.');
415	  let body;
416	  try {
417	    body = await readJson(req);
418	  } catch (err) {
419	    return orderError(res, 400, 'invalid_request', err.message);
420	  }
421	  if (!ALL_PLANS.some((p) => p.id === body.planId)) {
422	    return orderError(res, 400, 'invalid_plan', 'Unknown planId.');
