465	function handlePaySubmit(ctx, id) {
466	  const { res, url } = ctx;
467	  const order = state.orders.get(id);
468	  if (!order) return sendHtml(res, 404, providerPage('Not found', '<h1>Unknown order</h1>'));
469	  if (order.outcome) return redirect(res, orderReturnUrl(order));
470	  if (url.searchParams.get('action') === 'cancel') {
471	    order.outcome = 'failed';
472	    order.settleAt = Date.now();
473	    return redirect(res, orderReturnUrl(order, { cancelled: '1' }));
474	  }
475	  switch (order.scenario) {
476	    case 'payment_declined':
477	      order.outcome = 'failed';
478	      order.settleAt = Date.now() + ms(1000);
479	      break;
480	    case 'payment_slow':
481	      order.outcome = 'paid';
482	      order.settleAt = Date.now() + ms(45000);
483	      break;
484	    case 'payment_requires_action':
485	      order.awaitingAction = true;
486	      return redirect(res, `/mock-pay/${encodeURIComponent(order.id)}/challenge`);
487	    default:
488	      order.outcome = 'paid';
489	      order.settleAt = Date.now() + ms(3000);
