491	  return redirect(res, orderReturnUrl(order));
492	}
493	
494	function handleChallengePage(ctx, id) {
495	  const order = state.orders.get(id);
496	  if (!order) return sendHtml(ctx.res, 404, providerPage('Not found', '<h1>Unknown order</h1>'));
497	  if (order.outcome) return redirect(ctx.res, orderReturnUrl(order));
