500	
501	function handleChallengeComplete(ctx, id) {
502	  const { res, url } = ctx;
503	  const order = state.orders.get(id);
504	  if (!order) return sendHtml(res, 404, providerPage('Not found', '<h1>Unknown order</h1>'));
505	  if (!order.outcome) {
506	    order.awaitingAction = false;
507	    if (url.searchParams.get('result') === 'approve') {
508	      order.outcome = 'paid';
509	      order.settleAt = Date.now() + ms(3000);
510	    } else {
511	      order.outcome = 'failed';
512	      order.settleAt = Date.now();
513	    }
514	  }
515	  return redirect(res, orderReturnUrl(order));
516	}
517	
518	function handleCms(ctx) {
519	  const { res, url } = ctx;
520	  const market = (url.searchParams.get('market') || '').toUpperCase();
521	  const locale = (url.searchParams.get('locale') || '').toLowerCase();
522	  if (!/^[A-Z]{2}$/.test(market) || !/^[a-z]{2}$/.test(locale)) {
523	    return identityError(res, 400, 'market and locale are required');
524	  }
525	  const file = path.join(FIXTURES_DIR, 'cms', `plan-page.${market}.${locale}.json`);
526	  if (!fs.existsSync(file)) return identityError(res, 404, `No PlanPage entry for ${market}/${locale}`);
527	  return sendJson(res, 200, JSON.parse(fs.readFileSync(file, 'utf8')));
528	}
529	
530	// ---------------------------------------------------------------------------
531	// Router
532	// ---------------------------------------------------------------------------
533	
534	async function route(ctx) {
535	  const { req, res, url } = ctx;
536	  const p = url.pathname.replace(/\/+$/, '') || '/';
537	  const m = req.method;
538	  let match;
539	
540	  if (m === 'GET' && p === '/') return sendHtml(res, 200, landingPage(req, ctx.scenario));
541	  if (m === 'GET' && p === '/v1/plans') return handlePlans(ctx);
542	  if (m === 'POST' && p === '/v1/identity/sessions') return handleCreateIdentitySession(ctx);
543	  if (m === 'GET' && p === '/v1/me') return handleMe(ctx);
544	  if (m === 'POST' && p === '/v1/orders') return handleCreateOrder(ctx);
545	  if (m === 'GET' && (match = p.match(/^\/v1\/orders\/([\w-]+)$/))) return handleGetOrder(ctx, match[1]);
546	
547	  if (m === 'GET' && (match = p.match(/^\/mock-eid\/([\w-]+)$/))) return handleEidPage(ctx, match[1]);
548	  if (m === 'GET' && (match = p.match(/^\/mock-eid\/([\w-]+)\/complete$/))) return handleEidComplete(ctx, match[1]);
549	  if (m === 'GET' && (match = p.match(/^\/mock-pay\/([\w-]+)$/))) return handlePayPage(ctx, match[1]);
550	  if (m === 'GET' && (match = p.match(/^\/mock-pay\/([\w-]+)\/submit$/))) return handlePaySubmit(ctx, match[1]);
551	  if (m === 'GET' && (match = p.match(/^\/mock-pay\/([\w-]+)\/challenge$/))) return handleChallengePage(ctx, match[1]);
552	  if (m === 'GET' && (match = p.match(/^\/mock-pay\/([\w-]+)\/challenge\/complete$/))) return handleChallengeComplete(ctx, match[1]);
553	
554	  if (m === 'GET' && p === '/cms/v1/plan-pages') return handleCms(ctx);
555	
556	  if (m === 'GET' && (match = p.match(/^\/__mock\/scenario\/([\w]+)$/))) {
557	    if (!Object.prototype.hasOwnProperty.call(SCENARIOS, match[1])) return identityError(res, 404, 'Unknown scenario');
558	    addCookie(res, `${SCENARIO_COOKIE}=${match[1]}; Path=/; SameSite=Lax; Max-Age=3600`);
559	    return redirect(res, '/');
560	  }
561	  if ((m === 'POST' || m === 'GET') && p === '/__mock/reset') {
562	    resetState();
563	    return m === 'GET' ? redirect(res, '/') : sendJson(res, 200, { ok: true });
564	  }
565	  if (m === 'GET' && p === '/__mock/state') {
566	    return sendJson(res, 200, {
567	      scenario: ctx.scenario,
568	      sessions: state.sessions.size,
569	      customers: [...state.customers.values()],
570	      identitySessions: state.identitySessions.size,
571	      orders: [...state.orders.values()].map((o) => ({ id: o.id, planId: o.planId, status: orderStatus(o), scenario: o.scenario })),
572	    });
573	  }
574	
575	  return identityError(res, 404, 'Not found');
576	}
577	
578	async function handle(req, res) {
579	  const url = new URL(req.url, 'http://mock.local');
580	  setCors(req, res);
581	  if (req.method === 'OPTIONS') {
582	    res.writeHead(204);
583	    return res.end();
584	  }
585	  const cookies = parseCookies(req);
586	  const scenario = resolveScenario(req, url, cookies);
587	  if (!scenario) {
588	    return identityError(res, 400, `Unknown scenario. Valid: ${Object.keys(SCENARIOS).join(', ')}`);
589	  }
590	  if (url.searchParams.get('scenario') && !req.headers['x-scenario']) {
591	    addCookie(res, `${SCENARIO_COOKIE}=${scenario}; Path=/; SameSite=Lax; Max-Age=3600`);
592	  }
593	  const started = Date.now();
594	  res.on('finish', () => {
595	    if (!process.env.MOCK_QUIET) {
596	      console.log(`${req.method} ${url.pathname} [${scenario}] -> ${res.statusCode} (${Date.now() - started}ms)`);
597	    }
598	  });
599	  try {
600	    await route({ req, res, url, cookies, scenario });
601	  } catch (err) {
602	    console.error(err);
603	    if (!res.headersSent) identityError(res, 500, 'Mock server error');
604	  }
605	}
606	
607	function createServer() {
608	  return http.createServer((req, res) => {
609	    handle(req, res);
610	  });
611	}
612	
613	if (require.main === module) {
614	  const server = createServer();
615	  server.on('error', (err) => {
616	    if (err.code === 'EADDRINUSE') console.error(`Port ${PORT} is in use. Set PORT=<other> and try again.`);
617	    else console.error(err);
618	    process.exit(1);
619	  });
620	  server.listen(PORT, HOST, () => {
621	    console.log(`Nordlight mock server on http://${HOST === '127.0.0.1' ? 'localhost' : HOST}:${PORT}`);
622	    console.log(`Web origin for redirects: ${WEB_ORIGIN}   time scale: ${TIME_SCALE}x`);
623	    console.log('Open the address above to see and switch scenarios.');
624	  });
625	}
626	
627	module.exports = { createServer, resetState, SCENARIOS };

